import { deriveNetworkTemplateMatter, deriveNetworkTemplateEnergy, deriveNetworkTemplateThermodynamics } from './materialNetworkTemplates';
import ejemplos from './ejemplosDemostracion.json';
import type {HojaMotor} from './hojasMotor';
import type {SolicitudEnsamblajeV2} from './contratoEnsamblajeV2';
import {nuevaHoja} from './hojasMotor';

/** Two demonstration worksheets (not tests): generated by tests/generar_ejemplos_demostracion.py. */
export function crearHojasDemostracion():HojaMotor[]{
  return ejemplos.map(e=>{
    const s=structuredClone(e.solicitud) as unknown as SolicitudEnsamblajeV2;s.solicitudId='configuracion';deriveNetworkTemplateMatter(s);deriveNetworkTemplateEnergy(s);deriveNetworkTemplateThermodynamics(s);
    return {...nuevaHoja(e.nombre),id:`motor-demo-v1-${e.id}`,balances:{materia:true,energia:true,momento:false},redTermodinamica:{solicitud:s,nombres:Object.fromEntries([
      ...s.volumenes.map(v=>[`volumen:${v.id}`,e.volumen]),...s.corrientes.map(c=>[`corriente:${c.id}`,'Vapor extraído']),...s.intercambiosTermicos.map(q=>[`calor:${q.id}`,'Calentamiento']),
    ])}};
  });
}
